SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);Alarm(200);tt:=Cputime();J:=JH(81,[28]);b:=0;rows:=[* *];for p in [2,7,13,19,31,37,43,61,67,73] do f:=FrobeniusPolynomial(J,p);e:=p mod 3 eq 1 select 1 else 2;num:=Integers()!(Evaluate(f,1)*(e eq 1 select 1 else Evaluate(f,-1)));b:=GCD(b,num);Append(~rows,[*p,e,num,Valuation(num,2),b,Valuation(b,2)*]);print "M327_TORSION_GCD",p,e,Valuation(num,2),b,Valuation(b,2),Cputime(tt);end for;Write("work/deg10/continuation_20261031b/M3N27/torsion_gcd.m",Sprint(rows):Overwrite:=true);print "D31B_M327_TORSION_GCD_COMPLETE",b,Cputime(tt);quit;
